<?php
require_once __DIR__ . '/_init.php'; require_perfil(['Admin']); $erro='';
if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $acao=$_POST['acao']??''; $id=(int)($_POST['id']??0); try { if($acao==='excluir') { $s=$pdo->prepare('DELETE FROM conteudos WHERE id=:id'); $s->execute([':id'=>$id]); audit($pdo,'excluiu conteúdo','conteudos',$id); header('Location: conteudos.php?ok=1'); exit; } if($acao==='salvar') { $titulo=trim((string)($_POST['titulo']??'')); $resumo=trim((string)($_POST['resumo']??'')); $corpo=trim((string)($_POST['corpo']??'')); $cat=(int)($_POST['categoria_id']??0); $status=(string)($_POST['status']??'rascunho'); if($titulo===''||$resumo===''||$corpo===''||$cat<1||!in_array($status,['rascunho','publicado','arquivado'],true)) throw new RuntimeException('Preencha título, resumo, texto e categoria.'); $img=upload_image('imagem'); $slug=trim((string)($_POST['slug']??'')); if($slug==='') $slug=$titulo; $slug=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$slug); $slug=strtolower(trim(preg_replace('/[^a-zA-Z0-9]+/','-',$slug),'-')); $slug=$slug?:bin2hex(random_bytes(6)); if($id) { if($img) { $s=$pdo->prepare('UPDATE conteudos SET titulo=:t,slug=:slug,resumo=:r,corpo=:c,categoria_id=:cat,status=:st,imagem_capa=:img,publicado_em=CASE WHEN :st2=\'publicado\' THEN COALESCE(publicado_em,NOW()) ELSE NULL END WHERE id=:id'); $s->execute([':t'=>$titulo,':slug'=>$slug,':r'=>$resumo,':c'=>$corpo,':cat'=>$cat,':st'=>$status,':img'=>$img,':st2'=>$status,':id'=>$id]); } else { $s=$pdo->prepare('UPDATE conteudos SET titulo=:t,slug=:slug,resumo=:r,corpo=:c,categoria_id=:cat,status=:st,publicado_em=CASE WHEN :st2=\'publicado\' THEN COALESCE(publicado_em,NOW()) ELSE NULL END WHERE id=:id'); $s->execute([':t'=>$titulo,':slug'=>$slug,':r'=>$resumo,':c'=>$corpo,':cat'=>$cat,':st'=>$status,':st2'=>$status,':id'=>$id]); } audit($pdo,'editou conteúdo','conteudos',$id); } else { $s=$pdo->prepare('INSERT INTO conteudos(titulo,slug,resumo,corpo,imagem_capa,categoria_id,autor_id,status,publicado_em) VALUES(:t,:slug,:r,:c,:img,:cat,:autor,:st,CASE WHEN :st2=\'publicado\' THEN NOW() ELSE NULL END) RETURNING id'); $s->execute([':t'=>$titulo,':slug'=>$slug,':r'=>$resumo,':c'=>$corpo,':img'=>$img,':cat'=>$cat,':autor'=>$_SESSION['usuario_id'],':st'=>$status,':st2'=>$status]); audit($pdo,'criou conteúdo','conteudos',(int)$s->fetchColumn()); } header('Location: conteudos.php?ok=1'); exit; } } catch(Throwable $e) { $erro=$e instanceof RuntimeException?$e->getMessage():'Não foi possível salvar. Confira se o endereço (slug) já existe e se a imagem é válida.'; } }
$edit=null; if(isset($_GET['editar'])) { $s=$pdo->prepare('SELECT * FROM conteudos WHERE id=:id'); $s->execute([':id'=>(int)$_GET['editar']]); $edit=$s->fetch(); }
$cats=$pdo->query('SELECT id,nome FROM categorias WHERE ativo=TRUE ORDER BY ordem,nome')->fetchAll(); $items=$pdo->query('SELECT c.id,c.titulo,c.status,c.publicado_em,cat.nome AS categoria FROM conteudos c JOIN categorias cat ON cat.id=c.categoria_id ORDER BY c.id DESC')->fetchAll(); admin_header('Gerenciar notícias'); if($erro): ?><div class="alert error"><?= h($erro) ?></div><?php endif; ?><section class="panel"><h2><?= $edit?'Editar publicação':'Nova notícia ou publicação' ?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="salvar"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Título<input name="titulo" required maxlength="200" value="<?= h($edit['titulo']??'') ?>"></label><label>Slug (endereço)<input name="slug" maxlength="200" value="<?= h($edit['slug']??'') ?>"></label><label>Resumo<textarea name="resumo" required rows="3"><?= h($edit['resumo']??'') ?></textarea></label><label>Texto completo<textarea name="corpo" required rows="9"><?= h($edit['corpo']??'') ?></textarea></label><label>Categoria<select name="categoria_id" required><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>" <?= ((int)($edit['categoria_id']??0)===(int)$c['id'])?'selected':'' ?>><?= h($c['nome']) ?></option><?php endforeach; ?></select></label><label>Imagem de capa (JPG, PNG, WEBP ou GIF; até 5 MB)<input type="file" name="imagem" accept="image/jpeg,image/png,image/webp,image/gif"></label><?php if(!empty($edit['imagem_capa'])): ?><img class="thumb" src="../<?= h($edit['imagem_capa']) ?>" alt="Capa atual"><?php endif; ?><label>Estado<select name="status"><option value="rascunho" <?= (($edit['status']??'')==='rascunho')?'selected':'' ?>>Rascunho</option><option value="publicado" <?= (($edit['status']??'')==='publicado')?'selected':'' ?>>Publicado</option><option value="arquivado" <?= (($edit['status']??'')==='arquivado')?'selected':'' ?>>Arquivado</option></select></label><button type="submit">Salvar publicação</button></form></section><section class="panel"><h2>Publicações existentes</h2><?php foreach($items as $it): ?><article class="item"><div><h3><?= h($it['titulo']) ?></h3><p><?= h($it['categoria']) ?> · <?= h($it['status']) ?></p></div><div class="actions"><a class="button secondary" href="conteudos.php?editar=<?= (int)$it['id'] ?>">Editar</a><form method="post"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="acao" value="excluir"><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><button class="danger" type="submit">Excluir</button></form></div></article><?php endforeach; ?></section><?php admin_footer();
